#!/usr/bin/env python3
"""
Run this ONCE from your repo root (pathwaygh-advisor):

    python finalize_ucc_addition.py

Writes every changed/new file to its exact correct path, then run
finalize_ucc_check.py to confirm before committing.
"""
import base64, os

PAYLOAD = {'data/structured/institution_programmes.json': '', 'app/tools/institution_programme_lookup.py': '', 'tests/test_institution_programme_lookup.py': '', 'tests/test_eligibility_checker.py': '', 'tests/test_api.py': '', 'tests/test_orchestrator.py': '', 'scripts/run_eval.py': ''}

def main():
    for dest, b64 in PAYLOAD.items():
        dest_path = dest.replace("/", os.sep)
        os.makedirs(os.path.dirname(dest_path) or ".", exist_ok=True)
        with open(dest_path, "wb") as f:
            f.write(base64.b64decode(b64))
        print(f"wrote {dest_path} ({len(base64.b64decode(b64))} bytes)")
    print()
    print("Done. Now run: python finalize_ucc_check.py")

if __name__ == "__main__":
    main()
